);
GO

CREATE TABLE [dbo].[emission_factor] (
    [id] [bigint] IDENTITY(1,1) NOT NULL,
    [data_type] [varchar](255) NULL,
    [database_source] [varchar](255) NULL,
    [factor_value] [decimal](18, 10) NOT NULL,
    [unit] [varchar](255) NULL,
    [currency] [varchar](255) NULL,
    [reference_year] [int] NULL CONSTRAINT [DF__emission___refer__59C55456] DEFAULT ((2024)),
    [has_margins] [bit] NULL CONSTRAINT [DF__emission___has_m__5AB9788F] DEFAULT ((1)),
    [created_at] [datetime] NULL CONSTRAINT [DF__emission___creat__5BAD9CC8] DEFAULT (getdate()),
    [updated_at] [datetime] NULL CONSTRAINT [DF__emission___updat__5CA1C101] DEFAULT (getdate()),
    [carbon_reference_id] [bigint] NULL,
    [uncertainty_percent] [numeric](8, 2) NULL,
    [validity_label] [varchar](40) NULL,
    CONSTRAINT [PK__emission__3213E83FAB55E25F] PRIMARY KEY CLUSTERED ([id] ASC)
);
GO

CREATE TABLE [dbo].[emission_measure] (
